def _stem_word(word: str) -> str:
    if not word:
        return ""
    w = word.lower()
    exc = _EXC.get(w)
    if exc is not None:
        return exc
    wl = len(w)
    t = _jget(w[-3:]) if wl >= 3 else None
    if t is not None:
        node, nd, best, rest = t
        if nd > wl:
            best = None
            for nd, op in rest:
                if nd <= wl:
                    best = op
                    break
